mapper.select:
SELECT  FROM wechat_offer_task

    AND create_time >= #{beginTime}
    AND create_time <= #{endTime}
    AND handle_status = #{handleStatus}
    AND task_type = #{taskType}
    AND pn_original LIKE CONCAT('%', #{pnKeyword}, '%')
    AND ori_target LIKE CONCAT('%', #{oriTarget}, '%')

        AND (pn_original LIKE CONCAT('%', #{queryKeyword}, '%')
          OR ori_msg LIKE CONCAT('%', #{queryKeyword}, '%')
          OR send_content LIKE CONCAT('%', #{queryKeyword}, '%'))


        AND (send_target IS NULL OR JSON_LENGTH(send_target) = 0
             OR last_error = 'UNMAPPED_CHAT' OR last_error LIKE 'UNMAPPED_CHAT:%')


ORDER BY create_time DESC, id DESC

SELECT  FROM wechat_offer_task
WHERE source_username = #{sourceUsername} AND source_local_id = #{sourceLocalId}
  AND task_type = #{taskType} AND pn_normalized = #{pnNormalized} AND send_type = #{sendType}
LIMIT 1

mapper.update:
UPDATE wechat_offer_task
SET send_attempts = send_attempts + 1, last_attempt_at = #{attemptAt}, update_time = NOW()
WHERE id = #{id}

UPDATE wechat_offer_task
SET last_error = #{error}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT  FROM wechat_offer_task
WHERE handle_status = 'APPROVED_PENDING_SEND'
  AND send_target IS NOT NULL
  AND send_attempts < #{maxAttempts}
  AND (last_error IS NULL OR last_error NOT LIKE 'GATEWAY_RESULT_UNKNOWN%')
ORDER BY id ASC LIMIT #{max}

SELECT  FROM wechat_offer_task
WHERE handle_status = 'APPROVED_PENDING_SEND'
  AND task_type = #{taskType}
  AND send_type = #{sendType}
  AND JSON_CONTAINS(send_target, JSON_OBJECT('name', #{targetName}))
ORDER BY id ASC LIMIT #{max}
